from functools import reduce

def find_sequence(n, k):
    if n < k:
        return -1

    base = n // k
    remainder = n % k

    seq = [base] * k
    for i in range(remainder):
        seq[i] += 1

    current_gcd = reduce(gcd, seq)

    if current_gcd == 1:
        return seq

    # Try to increase the GCD
    while True:
        new_seq = []
        for i in range(k):
            if seq[i] > 1:
                new_seq.append(seq[i] - 1)
            else:
                new_seq.append(seq[i])

        new_gcd = reduce(gcd, new_seq)
        if new_gcd > current_gcd:
            return new_seq

        if new_gcd == 1:
            break

        seq = new_seq

    return -1

